import {reactFetchJSON} from '@github-ui/verified-fetch'
import {
  ActionList,
  ActionMenu,
  Banner,
  FormControl,
  IconButton,
  Link,
  Stack,
  TextInput,
  ToggleSwitch,
} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {PencilIcon} from '@primer/octicons-react'
import {useRef, useState} from 'react'
import type {RunnerType} from '../types'
import {SectionHeading} from '../traditional/components/Ui'
import {ControlGroup} from '@github-ui/control-group'

type RunnerTypeSelectionProps = {
  initialRunnerType?: RunnerType
  initialRunnerLabels?: string
  initialRunnerGroupName?: string
  initialAllowRepoCustomRunner?: boolean
  /**
   * Endpoint to PUT runner setting changes to. The same endpoint is used for both
   * the org's coding-agent page and the standalone Runner type page; the dotcom
   * controller switches based on the path.
   */
  endpoint: string
  /**
   * Display name for the agent(s) whose runner configuration is being edited.
   * Used throughout copy on the page and in the edit dialog. Defaults to
   * "Copilot cloud agent" for the inline coding-agent settings page; the
   * standalone Runner type page passes a combined name covering all agents
   * the configuration applies to.
   */
  agentName?: string
}

function getRunnerTypes(agentName: string): Array<{value: RunnerType; label: string; description: string}> {
  return [
    {
      value: 'standard',
      label: 'Standard GitHub runner',
      description: `${agentName} will use standard GitHub runners.`,
    },
    {
      value: 'labeled',
      label: 'Labeled runner',
      description: `${agentName} will use labeled GitHub or self-hosted runners that you may define.`,
    },
  ]
}

export function RunnerTypeSelection({
  initialRunnerType = 'standard',
  initialRunnerLabels = '',
  initialRunnerGroupName = '',
  initialAllowRepoCustomRunner = true,
  endpoint,
  agentName = 'Copilot cloud agent',
}: RunnerTypeSelectionProps) {
  const [runnerType, setRunnerType] = useState<RunnerType>(initialRunnerType)
  const [runnerLabels, setRunnerLabels] = useState<string>(initialRunnerLabels)
  const [runnerGroupName, setRunnerGroupName] = useState<string>(initialRunnerGroupName)
  const [allowRepoCustomRunner, setAllowRepoCustomRunner] = useState<boolean>(initialAllowRepoCustomRunner)
  const [errorBannerMessage, setErrorBannerMessage] = useState<string | null>(null)
  const [isDialogOpen, setIsDialogOpen] = useState(false)
  const [isSaving, setIsSaving] = useState(false)

  // Dialog-local state (reset on open/cancel)
  const [dialogRunnerType, setDialogRunnerType] = useState<RunnerType>(initialRunnerType)
  const [dialogRunnerLabels, setDialogRunnerLabels] = useState<string>(initialRunnerLabels)
  const [dialogRunnerGroupName, setDialogRunnerGroupName] = useState<string>(initialRunnerGroupName)
  const [dialogErrorMessage, setDialogErrorMessage] = useState<string | null>(null)

  const editButtonRef = useRef<HTMLButtonElement>(null)

  const runnerTypes = getRunnerTypes(agentName)
  const currentRunnerTypeDisplay = runnerTypes.find(rt => rt.value === runnerType)?.label ?? 'Standard GitHub runner'

  const openDialog = () => {
    setDialogRunnerType(runnerType)
    setDialogRunnerLabels(runnerLabels)
    setDialogRunnerGroupName(runnerGroupName)
    setDialogErrorMessage(null)
    setIsDialogOpen(true)
  }

  const closeDialog = () => {
    setDialogErrorMessage(null)
    setIsDialogOpen(false)
  }

  const DEFAULT_ERROR_MESSAGE = 'Failed to update runner settings, please try again later.'

  const saveRunnerSettings = async () => {
    setDialogErrorMessage(null)
    setIsSaving(true)
    try {
      const response = await reactFetchJSON(endpoint, {
        method: 'PUT',
        body: {
          runner_type: dialogRunnerType,
          runner_labels: dialogRunnerLabels,
          runner_group_name: dialogRunnerGroupName,
          allow_repo_custom_runner: allowRepoCustomRunner,
        },
      })
      if (!response.ok) {
        let body = null
        try {
          body = await response.json()
        } catch {
          // response body is not JSON
        }
        setDialogErrorMessage(body?.error || DEFAULT_ERROR_MESSAGE)
        return
      }
      setRunnerType(dialogRunnerType)
      setRunnerLabels(dialogRunnerLabels)
      setRunnerGroupName(dialogRunnerGroupName)
      setIsDialogOpen(false)
    } catch {
      setDialogErrorMessage(DEFAULT_ERROR_MESSAGE)
    } finally {
      setIsSaving(false)
    }
  }

  const toggleAllowRepoCustomRunner = async (checked: boolean) => {
    setAllowRepoCustomRunner(checked)
    setErrorBannerMessage(null)
    try {
      const response = await reactFetchJSON(endpoint, {
        method: 'PUT',
        body: {
          runner_type: runnerType,
          runner_labels: runnerLabels,
          runner_group_name: runnerGroupName,
          allow_repo_custom_runner: checked,
        },
      })
      if (!response.ok) {
        let body = null
        try {
          body = await response.json()
        } catch {
          // response body is not JSON
        }
        setAllowRepoCustomRunner(!checked)
        setErrorBannerMessage(body?.error || DEFAULT_ERROR_MESSAGE)
        return
      }
    } catch {
      setAllowRepoCustomRunner(!checked)
      setErrorBannerMessage(DEFAULT_ERROR_MESSAGE)
    }
  }

  return (
    <>
      {errorBannerMessage !== null && (
        <Banner
          variant="critical"
          title="Failed to save changes"
          hideTitle
          className="tmp-mb-3"
          onDismiss={() => setErrorBannerMessage(null)}
        >
          {errorBannerMessage}
        </Banner>
      )}
      <Stack gap="condensed">
        <SectionHeading name="Runner type" />
        <p className="mb-0">
          Select the default runner type for {agentName} sessions. Repositories in this organization will use the
          selected runner type unless overridden at the repository level.{' '}
          <Link href="https://docs.github.com/actions/concepts/runners" inline>
            Learn about GitHub Actions runners.
          </Link>
        </p>
      </Stack>
      <div className="tmp-mt-3">
        <ControlGroup className="borderColor-default px-1">
          <ControlGroup.Item>
            <ControlGroup.Title>Runner type configuration</ControlGroup.Title>
            <ControlGroup.Description>Select the runner type for {agentName} sessions.</ControlGroup.Description>
            <ControlGroup.Custom>
              <div className="d-flex flex-items-center gap-2">
                <span className="color-fg-muted text-small">{currentRunnerTypeDisplay}</span>
                <IconButton
                  ref={editButtonRef}
                  icon={PencilIcon}
                  aria-label="Edit runner type"
                  variant="invisible"
                  onClick={openDialog}
                />
              </div>
            </ControlGroup.Custom>
          </ControlGroup.Item>
          <ControlGroup.Item>
            <ControlGroup.Title id="allow-repo-custom-runner-label">
              Allow repositories to customize the runner type
            </ControlGroup.Title>
            <ControlGroup.Description>
              When enabled, repositories can specify their own runner via their copilot-setup-steps.yml file.
            </ControlGroup.Description>
            <ControlGroup.Custom>
              <ToggleSwitch
                defaultChecked={allowRepoCustomRunner}
                onChange={toggleAllowRepoCustomRunner}
                size="small"
                aria-labelledby="allow-repo-custom-runner-label"
              />
            </ControlGroup.Custom>
          </ControlGroup.Item>
        </ControlGroup>
      </div>
      {isDialogOpen && (
        <Dialog
          title={`Edit runner type for ${agentName}`}
          onClose={closeDialog}
          width="large"
          returnFocusRef={editButtonRef}
          footerButtons={[
            {buttonType: 'default', content: 'Cancel', onClick: closeDialog},
            {
              buttonType: 'primary',
              content: 'Save runner selection',
              onClick: saveRunnerSettings,
              disabled: isSaving,
              loading: isSaving,
            },
          ]}
        >
          <div style={{display: 'flex', flexDirection: 'column', gap: '16px'}}>
            {dialogErrorMessage && (
              <Banner
                variant="critical"
                title="Failed to save changes"
                hideTitle
                onDismiss={() => setDialogErrorMessage(null)}
              >
                {dialogErrorMessage}
              </Banner>
            )}
            <FormControl>
              <FormControl.Label>Runner type</FormControl.Label>
              <ActionMenu>
                <ActionMenu.Button>
                  {runnerTypes.find(rt => rt.value === dialogRunnerType)?.label ?? 'Standard GitHub runner'}
                </ActionMenu.Button>
                <ActionMenu.Overlay>
                  <ActionList selectionVariant="single">
                    {runnerTypes.map(rt => (
                      <ActionList.Item
                        key={rt.value}
                        selected={dialogRunnerType === rt.value}
                        onSelect={() => setDialogRunnerType(rt.value)}
                      >
                        <ActionList.LeadingVisual />
                        {rt.label}
                        <ActionList.Description variant="block">{rt.description}</ActionList.Description>
                      </ActionList.Item>
                    ))}
                  </ActionList>
                </ActionMenu.Overlay>
              </ActionMenu>
            </FormControl>

            {dialogRunnerType === 'labeled' && (
              <>
                <div>
                  <p className="text-semibold mb-1">Runner information</p>
                  <p className="color-fg-muted text-small mb-2">You must provide a runner group name and/or label.</p>
                </div>
                <div
                  style={{
                    border: '1px solid var(--borderColor-default)',
                    borderRadius: '6px',
                    padding: '16px',
                    display: 'flex',
                    flexDirection: 'column',
                    gap: '16px',
                  }}
                >
                  <FormControl>
                    <FormControl.Label>Runner group name</FormControl.Label>
                    <TextInput
                      value={dialogRunnerGroupName}
                      onChange={e => setDialogRunnerGroupName(e.target.value)}
                      placeholder="Existing name"
                      maxLength={128}
                      block
                    />
                    <FormControl.Caption>
                      {dialogRunnerGroupName ? (
                        <span className="color-fg-attention">
                          Verify spelling matches an existing runner group to ensure proper setup.
                        </span>
                      ) : null}
                    </FormControl.Caption>
                  </FormControl>
                  <FormControl>
                    <FormControl.Label>Runner label</FormControl.Label>
                    <FormControl.Caption>
                      {dialogRunnerLabels ? (
                        <span className="color-fg-attention">
                          Verify spelling matches an existing label to ensure proper setup.
                        </span>
                      ) : (
                        <Link
                          href="https://docs.github.com/en/actions/how-tos/manage-runners/self-hosted-runners/apply-labels"
                          inline
                        >
                          Learn how to use or create custom labels.
                        </Link>
                      )}
                    </FormControl.Caption>
                    <TextInput
                      value={dialogRunnerLabels}
                      onChange={e => setDialogRunnerLabels(e.target.value)}
                      placeholder="Existing label"
                      maxLength={256}
                      block
                    />
                  </FormControl>
                </div>
              </>
            )}
          </div>
        </Dialog>
      )}
    </>
  )
}
