import {currency as formatCurrency} from '@github-ui/formatters'
import {ssrSafeLocation} from '@github-ui/ssr-utils'
import {Link} from '@primer/react'
import {clsx} from 'clsx'
import type React from 'react'
import {COPILOT_BUSINESS_LICENSE_COST} from '../../constants'
import styles from './PulseCheck.module.css'

function Card({children, className, ...rest}: React.PropsWithChildren<React.HTMLAttributes<HTMLDivElement>>) {
  return (
    <div className={clsx(styles.card, className)} {...rest}>
      {children}
    </div>
  )
}

const PulseCard = (props: React.PropsWithChildren<object>) => <Card className={styles.pulseCard}>{props.children}</Card>

export function PulseCheck(props: {licenses: number; slug: string}) {
  return (
    <section className={styles.pulseSection} aria-label="Insights">
      <PulseCard>
        <p className={styles.cardTitle}>Total consumed seats</p>
        <p className={styles.cardValue} data-testid="license-pulse-text">
          {props.licenses}
        </p>
        <p className={styles.cardDescription}>Number of unique members with access to Copilot Business.</p>
      </PulseCard>
      <PulseCard>
        <div className={styles.cardHeader}>
          <p className={styles.cardTitle}>Estimated monthly cost</p>
          <Link target="_blank" href={`${ssrSafeLocation.origin}/enterprises/${props.slug}/settings/billing`}>
            Review billing details
          </Link>
        </div>
        <p className={styles.cardValue} data-testid="cost-pulse-text">
          {`${formatCurrency(props.licenses * COPILOT_BUSINESS_LICENSE_COST)}`}
        </p>
        <p className={styles.cardDescription} data-testid="per-seat-pulse-text">
          Each purchased seat is ${COPILOT_BUSINESS_LICENSE_COST} USD/month.
        </p>
      </PulseCard>
    </section>
  )
}
