import {pluralize} from '../../helpers/text'
import {currency} from '@github-ui/formatters'
import styles from './NewAssignmentsEstimatedCost.module.css'

type Props = {
  seatCount: number
  seatCost: number
}

export function NewAssignmentsEstimatedCost(props: Props) {
  return (
    <section aria-label="New assignments estimated cost">
      <div role="status">
        <span>
          <p className={styles.costSummary}>
            {pluralize(props.seatCount, 'unique seat', 's')} with an approximate cost of{' '}
            {currency(props.seatCost * props.seatCount)} will be added.
          </p>
          <span className={styles.mutedText}>You will not be charged twice for members across multiple teams. </span>
        </span>
      </div>
    </section>
  )
}
