import {ShieldLockIcon} from '@primer/octicons-react'
import PreviewFeatureHeading from './PreviewFeatureHeading'

function allowlistTitle(allowlistAssigned?: boolean, allowlistName?: string): string {
  if (allowlistAssigned && allowlistName) {
    return allowlistName
  } else if (allowlistAssigned === false) {
    return 'Disabled'
  } else {
    return 'Managed by your enterprise'
  }
}

export default function McpAssignedAllowlist({
  allowlistAssigned,
  allowlistName,
}: {
  allowlistAssigned?: boolean
  allowlistName?: string
}) {
  return (
    <>
      <div data-testid="cfb-policies-mcp-assigned-allowlist-feature" style={{maxWidth: 750}}>
        <PreviewFeatureHeading title="Assigned allowlist" beta={false} />
        If enabled, only MCP servers on the assigned allowlist can be used by members of this organization.
      </div>
      <span
        data-testid="cfb-policies-mcp-assigned-allowlist-feature-locked"
        className="d-flex flex-items-center gap-1 color-fg-muted"
      >
        <ShieldLockIcon size={16} /> {allowlistTitle(allowlistAssigned, allowlistName)}
      </span>
    </>
  )
}
