import {ShieldLockIcon} from '@primer/octicons-react'
import PreviewFeatureHeading from './PreviewFeatureHeading'

function blockLocalServersEnabledText(enabled: boolean | undefined) {
  if (enabled === true) {
    return 'Enabled'
  } else if (enabled === false) {
    return 'Disabled'
  } else {
    return ''
  }
}

export default function McpBlockLocalServers({local_server_block}: {local_server_block?: boolean}) {
  return (
    <>
      <div data-testid="cfb-policies-mcp-block-local-servers-feature" style={{maxWidth: 750}}>
        <PreviewFeatureHeading title="Block all local servers" beta={false} />
        Recommended for strict security. When enabled, only remote (hosted) MCP servers are allowed. Local servers
        cannot be used even if listed in the registry.
      </div>
      <span
        data-testid="cfb-policies-mcp-block-local-servers-feature-locked"
        className="d-flex flex-items-center gap-1 color-fg-muted"
      >
        <ShieldLockIcon size={16} /> {blockLocalServersEnabledText(local_server_block) || 'Managed by your enterprise'}
      </span>
    </>
  )
}
