import {ControlGroup} from '@github-ui/control-group'
import {ActionList, ActionMenu} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {useState} from 'react'
import {useUpdateOrgAutomationsDisabledMutation} from '../hooks/use-org-automations-disabled-mutation'
import styles from './OrgAutomationsSettings.module.css'

type FieldStatus = {status: 'error' | 'success'; message: string}

export function OrgAutomationsSettings({
  endpoint,
  initialDisabled = null,
}: {
  endpoint: string
  /**
   * The org's stored kill-switch policy. We treat `false` (explicitly allowed)
   * the same as `null` (no policy) in the UI, since both let repositories
   * decide and a repo can still set its own `true` to disable.
   */
  initialDisabled?: boolean | null
}) {
  const saveSetting = useUpdateOrgAutomationsDisabledMutation(endpoint)
  const [isDisabled, setIsDisabled] = useState<boolean>(initialDisabled === true)
  const [isSaving, setIsSaving] = useState<boolean>(false)
  const [fieldStatus, setFieldStatus] = useState<FieldStatus | null>(null)

  const handleSelect = async (next: boolean) => {
    if (next === isDisabled) return
    setIsSaving(true)
    // "Enabled" clears the policy entirely (null) so repositories decide;
    // "Disabled" writes a final `true` that overrides repo settings.
    const payload: boolean | null = next ? true : null
    try {
      const result = await saveSetting.mutateAsync(payload)
      setFieldStatus(null)
      setIsDisabled(result.automationsDisabled === true)
    } catch (error) {
      setFieldStatus({
        status: 'error',
        message: error instanceof Error ? error.message : 'An error occurred saving automations settings.',
      })
    } finally {
      setIsSaving(false)
    }
  }

  return (
    <ControlGroup.Item>
      <ControlGroup.Title id="org-automations-allow-label" className="d-flex flex-items-center gap-1">
        Allow automations
      </ControlGroup.Title>
      <ControlGroup.Description id="org-automations-allow-description">
        When enabled, users with repository write access can create automations that automatically run agents on a
        schedule or in response to events like new issues or updated pull requests.
        <div role="status" aria-live="polite">
          {fieldStatus && (
            <InlineMessage
              variant={fieldStatus.status === 'success' ? 'success' : 'critical'}
              size="small"
              className="mt-1"
            >
              {fieldStatus.message}
            </InlineMessage>
          )}
        </div>
      </ControlGroup.Description>
      <ControlGroup.Custom>
        <div className={styles.menuWrapper}>
          <ActionMenu>
            <ActionMenu.Button
              disabled={isSaving}
              aria-labelledby="org-automations-allow-label"
              aria-describedby="org-automations-allow-description"
              variant="default"
            >
              {isDisabled ? 'No repositories' : 'Let repositories decide'}
            </ActionMenu.Button>
            <ActionMenu.Overlay width="small">
              <ActionList selectionVariant="single">
                <ActionList.Item selected={!isDisabled} onSelect={() => handleSelect(false)}>
                  Let repositories decide
                  <ActionList.Description variant="block">
                    Repository admins decide where to enable automations
                  </ActionList.Description>
                </ActionList.Item>
                <ActionList.Item selected={isDisabled} onSelect={() => handleSelect(true)}>
                  No repositories
                  <ActionList.Description variant="block">Disabled across this organization</ActionList.Description>
                </ActionList.Item>
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </div>
      </ControlGroup.Custom>
    </ControlGroup.Item>
  )
}
