import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useCallback, useState, useMemo} from 'react'
import {Breadcrumbs, Button, IconButton, Heading, TextInput, Link, FormControl} from '@primer/react'
import {TrashIcon} from '@primer/octicons-react'
import {Blankslate, InlineMessage} from '@primer/react/experimental'
import type {CopilotSweAgentFirewallPayload, OrgFirewallConfig} from '../types'
import {useUpdateOrgFirewallSettingsMutation} from '../hooks/use-org-firewall-mutation'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {copilotForBusinessSweAgentFirewallRoute} from './swe-agent-firewall-route'

type FieldStatus = {status: 'error' | 'success'; message: string}
type ValidationResult = {isValid: boolean; error?: string}

// Domain regex pattern ported from Go
const DOMAIN_PATTERN =
  /^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)*[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.([a-z]{2,63})$|^[a-z0-9][a-z0-9-]{0,61}$/

function parseMarkdownLink(text: string): string {
  const markdownLinkPattern = /^\[([^\]]*)\]\(([^)]+)\)$/
  const match = text.match(markdownLinkPattern)
  return match?.[1] ?? text
}

function validateNewRule(rule: string): ValidationResult {
  const trimmedRule = parseMarkdownLink(rule.trim())

  if (trimmedRule === '') {
    return {isValid: false, error: 'Rule cannot be empty'}
  }

  // Check for IP address
  if (trimmedRule.split('.').length === 4) {
    const parts = trimmedRule.split('.')
    let isIP = true

    for (const part of parts) {
      if (part.length === 0 || !/^\d+$/.test(part)) {
        isIP = false
        break
      }
      const num = parseInt(part, 10)
      if (num < 0 || num > 255) {
        isIP = false
        break
      }
    }

    if (isIP) {
      return {isValid: true}
    }
  }

  // Check if it's a URL
  if (trimmedRule.includes('://')) {
    try {
      const parsedUrl = new URL(trimmedRule, window.location.origin)

      if (parsedUrl.port && parsedUrl.port !== '80' && parsedUrl.port !== '443') {
        return {
          isValid: false,
          error: 'Only ports 80 and 443 are supported for URL rules',
        }
      }

      if (parsedUrl.username || parsedUrl.password) {
        return {
          isValid: false,
          error: 'URLs with a username or password component are not allowed as they could contain secrets',
        }
      }

      if (parsedUrl.search.trim().length > 0) {
        return {
          isValid: false,
          error: 'URLs with query parameters are not allowed as they could contain secrets',
        }
      }

      return {isValid: true}
    } catch {
      return {isValid: false, error: 'Invalid URL format'}
    }
  }

  // Check domain
  if (!DOMAIN_PATTERN.test(trimmedRule.toLowerCase())) {
    return {
      isValid: false,
      error: 'Rule must be a valid domain, IP address, or URL',
    }
  }

  return {isValid: true}
}

function deepEqual(a: OrgFirewallConfig, b: OrgFirewallConfig): boolean {
  if (a.enabled !== b.enabled || a.useDefaultRules !== b.useDefaultRules || a.allowCustomRules !== b.allowCustomRules) {
    return false
  }
  if (a.rules.length !== b.rules.length) {
    return false
  }
  const setA = new Set(a.rules)
  for (const rule of b.rules) {
    if (!setA.has(rule)) return false
  }
  return true
}

export function OrgAllowlistSettingsEntrypointLegacy() {
  const {firewallConfiguration, endpoint} = useRoutePayload<CopilotSweAgentFirewallPayload>()
  return <OrgAllowlistSettingsPage firewallConfiguration={firewallConfiguration} endpoint={endpoint} />
}

export function OrgAllowlistSettingsEntrypoint() {
  const {data: payload} = useRouteQuery(copilotForBusinessSweAgentFirewallRoute, 'mainQuery')
  return <OrgAllowlistSettingsPage firewallConfiguration={payload.firewallConfiguration} endpoint={payload.endpoint} />
}

function OrgAllowlistSettingsPage({
  firewallConfiguration,
  endpoint,
}: {
  firewallConfiguration: OrgFirewallConfig
  endpoint: string
}) {
  const firewallEndpoint = `${endpoint}/firewall`
  const [config, setConfig] = useState<OrgFirewallConfig>(
    firewallConfiguration || {enabled: true, useDefaultRules: true, allowCustomRules: false, rules: []},
  )
  const [newRule, setNewRule] = useState('')
  const [fieldStatus, setFieldStatus] = useState<FieldStatus | null>(null)
  const [persistedFirewallConfig, updatePersistedFirewallConfig] = useState<OrgFirewallConfig>(
    firewallConfiguration || {enabled: true, useDefaultRules: true, allowCustomRules: false, rules: []},
  )
  const [validationError, setValidationError] = useState<string | null>(null)
  const saveSettings = useUpdateOrgFirewallSettingsMutation(firewallEndpoint)

  const hasUnsavedChanges = useMemo(() => {
    return !deepEqual(config, persistedFirewallConfig)
  }, [config, persistedFirewallConfig])

  const validation = useMemo(() => {
    if (!newRule.trim()) {
      return {isValid: false, error: null}
    }

    if (config.rules.includes(newRule.trim())) {
      return {isValid: false, error: 'This rule already exists'}
    }

    return validateNewRule(newRule)
  }, [newRule, config.rules])

  const handleAddRule = useCallback(() => {
    if (newRule.trim() && validation.isValid) {
      setConfig(prev => ({
        ...prev,
        rules: [...prev.rules, newRule.trim()],
      }))
      setNewRule('')
      setFieldStatus(null)
      setValidationError(null)
    } else if (newRule.trim()) {
      setValidationError(validation.error || null)
    }
  }, [newRule, validation.isValid, validation.error])

  const handleAddMultipleRules = useCallback(
    (rules: string[]) => {
      const validRules: string[] = []
      const invalidRules: string[] = []
      const seen = new Set(config.rules)

      for (const rule of rules) {
        const trimmedRule = parseMarkdownLink(rule.trim())
        if (trimmedRule) {
          if (seen.has(trimmedRule)) {
            invalidRules.push(trimmedRule)
          } else {
            const ruleValidation = validateNewRule(rule)
            if (ruleValidation.isValid) {
              validRules.push(trimmedRule)
              seen.add(trimmedRule)
            } else {
              invalidRules.push(trimmedRule)
            }
          }
        }
      }

      if (validRules.length > 0) {
        setFieldStatus(null)
        setConfig(prev => ({
          ...prev,
          rules: [...prev.rules, ...validRules],
        }))
      }

      if (invalidRules.length > 0) {
        setValidationError(
          `${invalidRules.length} rule${invalidRules.length === 1 ? ' is' : 's are'} invalid or already exist${
            invalidRules.length === 1 ? 's' : ''
          }: ${invalidRules.join(', ')}`,
        )
      }

      setNewRule('')
    },
    [config.rules],
  )

  const handleInputChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      setNewRule(e.target.value)
      if (validationError) {
        setValidationError(null)
      }
    },
    [validationError],
  )

  const handlePaste = useCallback(
    (e: React.ClipboardEvent<HTMLInputElement>) => {
      const pastedText = e.clipboardData.getData('text')

      const items = pastedText
        .split(/[,\n]+/)
        .map(item => parseMarkdownLink(item.trim()))
        .filter(item => item.length > 0)

      if (items.length > 0) {
        e.preventDefault()

        if (items.length === 1) {
          const singleItem = items[0]
          if (singleItem && !config.rules.includes(singleItem)) {
            const ruleValidation = validateNewRule(singleItem)
            if (ruleValidation.isValid) {
              setConfig(prev => ({
                ...prev,
                rules: [...prev.rules, singleItem],
              }))
              setNewRule('')
              setValidationError(null)
            } else {
              setNewRule(singleItem)
              setValidationError(ruleValidation.error || null)
            }
          } else if (singleItem && config.rules.includes(singleItem)) {
            setNewRule(singleItem)
            setValidationError('This rule already exists')
          } else {
            setNewRule(singleItem ?? '')
          }
        } else {
          handleAddMultipleRules(items)
        }
      }
    },
    [handleAddMultipleRules, config.rules],
  )

  const handleRemoveRule = useCallback((ruleToRemove: string) => {
    setConfig(prev => ({
      ...prev,
      rules: prev.rules.filter(rule => rule !== ruleToRemove),
    }))
    setFieldStatus(null)
  }, [])

  const handleNewRuleSubmit = useCallback(
    (e: React.FormEvent) => {
      e.preventDefault()
      handleAddRule()
    },
    [handleAddRule],
  )

  const handleSaveChanges = useCallback(
    async (e: React.MouseEvent) => {
      e.preventDefault()
      try {
        const result = await saveSettings.mutateAsync(config)
        if (result.requestFailed) {
          setFieldStatus({
            status: 'error',
            message: result.error || 'An error occurred saving allowlist settings.',
          })
        } else {
          setFieldStatus({status: 'success', message: 'Allowlist settings saved successfully!'})
          setConfig(result)
          updatePersistedFirewallConfig(result)
        }
      } catch {
        setFieldStatus({
          status: 'error',
          message: 'An error occurred saving allowlist settings.',
        })
      }
    },
    [saveSettings, config],
  )

  return (
    <div>
      <Breadcrumbs className="tmp-mb-3">
        <Breadcrumbs.Item href={endpoint}>{'Copilot cloud agent'}</Breadcrumbs.Item>
        <Breadcrumbs.Item selected>Internet access</Breadcrumbs.Item>
      </Breadcrumbs>

      <div>
        <Heading as="h2" className="Subhead-heading Subhead-heading--large">
          Custom allowlist
        </Heading>
        <p className="mb-0">
          Add items to the allowlist to enable {'Copilot cloud agent'} to access specific domains, IP addresses, or URLs
          across all repositories in this organization.{' '}
          <Link
            href="https://docs.github.com/en/copilot/how-tos/agents/copilot-coding-agent/customizing-or-disabling-the-firewall-for-copilot-coding-agent#allowlisting-additional-hosts-in-the-agents-firewall"
            target="_blank"
            inline
          >
            See the GitHub Docs for syntax and examples.
          </Link>
        </p>

        <form onSubmit={handleNewRuleSubmit} className="tmp-mt-3">
          <div className="d-flex flex-items-start gap-2">
            <FormControl className="width-full">
              <FormControl.Label visuallyHidden>Rule to add</FormControl.Label>
              <TextInput
                placeholder="e.g. https://example.com/a/path or example.com"
                value={newRule}
                block
                onChange={handleInputChange}
                onPaste={handlePaste}
                disabled={config.enabled === false}
                validationStatus={validationError ? 'error' : undefined}
              />
              {validationError && <FormControl.Validation variant="error">{validationError}</FormControl.Validation>}
            </FormControl>
            <Button type="submit" disabled={config.enabled === false}>
              Add rule
            </Button>
          </div>
        </form>

        <div className="tmp-mt-3 overflow-hidden border rounded-2">
          {config.rules.length > 0 ? (
            <>
              <div className="py-2 tmp-px-3 bgColor-muted d-flex flex-items-center flex-justify-between gap-3">
                <Heading as="h3" className="f5">
                  {`${config.rules.length} ${config.rules.length === 1 ? 'rule' : 'rules'}`}
                </Heading>
              </div>
              <ul>
                {config.rules
                  .slice()
                  .sort((a, b) => a.localeCompare(b))
                  .map(rule => (
                    <li
                      key={rule}
                      className="border-top py-2 tmp-pl-3 tmp-pr-3 d-flex flex-items-center flex-justify-between gap-3"
                    >
                      <span className="text-semibold">{rule}</span>
                      <IconButton
                        aria-label={`Delete rule ${rule}`}
                        icon={TrashIcon}
                        onClick={() => handleRemoveRule(rule)}
                        variant="invisible"
                        size="small"
                        disabled={config.enabled === false}
                      />
                    </li>
                  ))}
              </ul>
            </>
          ) : (
            <Blankslate>
              <Blankslate.Heading className="f5">No rules yet</Blankslate.Heading>
              <Blankslate.Description className="f5">
                Tip: Paste a list of rules into the input to add them all at once.
              </Blankslate.Description>
            </Blankslate>
          )}
        </div>

        {fieldStatus && (
          <InlineMessage variant={fieldStatus.status === 'success' ? 'success' : 'critical'} className="tmp-mt-3">
            {fieldStatus.message}
          </InlineMessage>
        )}

        <Button
          variant="primary"
          className="tmp-mt-3"
          disabled={saveSettings.isPending || !hasUnsavedChanges}
          onClick={handleSaveChanges}
        >
          Save changes
        </Button>
      </div>
    </div>
  )
}
