import {reactFetchJSON} from '@github-ui/verified-fetch'
import {ActionList, ActionMenu, Label} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {useState} from 'react'
import type {CopilotSweAgentPayload} from '../types'
import {ControlGroup} from '@github-ui/control-group'
import styles from './OrgAutomationTriggerPolicy.module.css'

export function OrgAutomationTriggerPolicy({payload}: {payload: CopilotSweAgentPayload}) {
  const {allow_read_access_triggers: initialValue, trigger_actor_policy_changed_callback_path} = payload

  const [policyValue, setPolicyValue] = useState<boolean>(initialValue !== true)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)

  const DEFAULT_ERROR_MESSAGE = 'Failed to update trigger actor policy, please try again later.'

  const handlePolicyChange = async (newValue: boolean) => {
    const previousValue = policyValue
    setPolicyValue(newValue)
    setErrorMessage(null)
    try {
      const response = await reactFetchJSON(trigger_actor_policy_changed_callback_path!, {
        method: 'PUT',
        body: {
          allow_read_access_triggers: !newValue,
        },
      })
      if (!response.ok) {
        setPolicyValue(previousValue)
        setErrorMessage(DEFAULT_ERROR_MESSAGE)
        return
      }
    } catch {
      setPolicyValue(previousValue)
      setErrorMessage(DEFAULT_ERROR_MESSAGE)
    }
  }

  const policyLabel = (value: boolean): string => {
    return value ? 'Enabled' : 'Let repositories decide'
  }

  return (
    <ControlGroup.Item>
      <ControlGroup.Title id="allow-read-triggers-label">
        Only allow automations to be triggered by users with write access <Label>Recommended</Label>
      </ControlGroup.Title>
      <ControlGroup.Description id="allow-read-triggers-description">
        When enabled, automations will only run if the user triggering the event has write access to the repository.
        When disabled, users can create automations that listen for events triggered by users without write access.
        <InlineMessage variant="warning" size="small" className="mt-1">
          Allowing automations to be triggered by users without write access to the repository increases risk of prompt
          injection attacks, where an untrusted user can cause an agent to take actions in the repository using the
          agent&apos;s permissions.
        </InlineMessage>
        <div role="status" aria-live="polite">
          {errorMessage !== null && (
            <InlineMessage variant="critical" size="small" className="mt-1">
              {errorMessage}
            </InlineMessage>
          )}
        </div>
      </ControlGroup.Description>
      <ControlGroup.Custom>
        <div className={styles.policyControl}>
          <ActionMenu>
            <ActionMenu.Button
              id="allow-read-triggers-button"
              aria-labelledby="allow-read-triggers-label allow-read-triggers-button"
              aria-describedby="allow-read-triggers-description"
              variant="default"
            >
              {policyLabel(policyValue)}
            </ActionMenu.Button>
            <ActionMenu.Overlay width="auto">
              <ActionList selectionVariant="single">
                <ActionList.Item selected={policyValue === true} onSelect={() => handlePolicyChange(true)}>
                  Enabled
                  <ActionList.Description variant="block">
                    Only users with write access can trigger automations across all repositories.
                  </ActionList.Description>
                </ActionList.Item>
                <ActionList.Item selected={policyValue === false} onSelect={() => handlePolicyChange(false)}>
                  Let repositories decide
                  <ActionList.Description variant="block">
                    Repository administrators control whether automations can be triggered by users without write
                    access.
                  </ActionList.Description>
                </ActionList.Item>
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        </div>
      </ControlGroup.Custom>
    </ControlGroup.Item>
  )
}
