import React, {useState} from 'react'
import {Link, ToggleSwitch} from '@primer/react'
import {ActionMenuButton, type ActionMenuButtonOption} from '../traditional/components/ActionMenuButton'
import PreviewFeatureHeading from './PreviewFeatureHeading'
import {enterpriseBudgetsUrl, orgBudgetsUrl, useOverageUpdate, type PolicyUpdate} from '../hooks/use-overages'
import type {CopilotForBusinessPoliciesPayload} from '../types'
import {ShieldLockIcon} from '@primer/octicons-react'
import BannerPortal from './BannerPortal'

// ContentDivider is a simple divider for use inside component content.
// Unlike the Divider from Ui.tsx which renders as <li>, this renders as a <div>
// to avoid invalid DOM nesting when used inside elements that are already <li>.
function ContentDivider() {
  return (
    <div
      style={{
        display: 'block',
        width: '100%',
        backgroundColor: 'var(--borderColor-default)',
        height: '1px',
        marginTop: 'var(--base-size-16)',
        marginBottom: 'var(--base-size-16)',
      }}
      aria-hidden="true"
    />
  )
}

interface Props {
  enterprise_name: string | null
  org_name: string
  payload: CopilotForBusinessPoliciesPayload
  enterprise_slug: string | null
}

interface AIOveragePolicy {
  id: string
  title: string
  description: string
  featureEnabled: boolean
  policyName:
    | 'copilot_premium_request'
    | 'spark'
    | 'coding_agent_premium_request'
    | 'copilot_ai_unit'
    | 'coding_agent_ai_unit'
    | 'spark_ai_unit'
  type: 'sku' | 'product'
}

export default function OveragesPolicy({enterprise_name, org_name, payload, enterprise_slug}: Props) {
  const tokenBasedBilling = payload.overages.token_based_billing === true
  const agentName = 'Copilot cloud agent'
  const agentShortName = 'Cloud Agent'

  const aiOveragePolicies: AIOveragePolicy[] = tokenBasedBilling
    ? [
        {
          id: 'coding-agent-ai-unit',
          title: `Opt in to ${agentShortName} AI Credits paid usage`,
          description: `Enables billing for ${agentShortName} AI Credits`,
          featureEnabled: payload.overages.coding_agent_ai_unit?.visible === true,
          policyName: 'coding_agent_ai_unit',
          type: 'sku',
        },
        {
          id: 'copilot-ai-unit',
          title: 'Opt in to Copilot AI Credits paid usage',
          description: 'Enables billing for Copilot AI Credits',
          featureEnabled: payload.overages.copilot_ai_unit?.visible === true,
          policyName: 'copilot_ai_unit',
          type: 'sku',
        },
        {
          id: 'spark-ai-unit',
          title: 'Opt in to Spark AI Credits paid usage',
          description: 'Enables billing for Spark AI Credits',
          featureEnabled: payload.overages.spark_ai_unit?.visible === true,
          policyName: 'spark_ai_unit',
          type: 'sku',
        },
      ]
    : [
        {
          id: 'copilot-premium-request',
          title: 'Opt in to Copilot premium request paid usage',
          description: 'Enables billing for Copilot premium requests',
          featureEnabled: true,
          policyName: 'copilot_premium_request',
          type: 'sku',
        },
        {
          id: 'spark-premium-request',
          title: 'Opt in to Spark premium request paid usage',
          description: 'Enables billing for Spark premium requests',
          featureEnabled: payload.spark.visible === true,
          policyName: 'spark',
          type: 'product',
        },
        {
          id: 'copilot-coding-agent-request',
          title: `Opt in to ${agentName} request paid usage`,
          description: `Enables billing for ${agentName} premium requests`,
          featureEnabled: true,
          policyName: 'coding_agent_premium_request',
          type: 'sku',
        },
      ]
  const actionMenuTitles = {
    enable: 'Enabled',
    selected: 'Enabled for selected products',
    disable: 'Disabled',
  }
  const enabledAIOveragePolicies = aiOveragePolicies.filter(type => type.featureEnabled)
  const determineOverageState = (): string => {
    const toggledCount = enabledAIOveragePolicies.filter(
      type => payload.overages[type.policyName]?.value === true,
    ).length

    if (toggledCount === 0) return 'disable'
    if (toggledCount === enabledAIOveragePolicies.length) return 'enable'
    return 'selected'
  }
  const entityName = enterprise_name ? 'enterprise' : 'organization'
  const [enabled, setEnabled] = useState<string>(() => determineOverageState())

  const options: ActionMenuButtonOption[] = [
    {
      id: 'enable',
      value: 'enable',
      title: actionMenuTitles.enable,
      description: tokenBasedBilling
        ? `Your ${entityName} will be billed for AI credit paid usage.`
        : `Your ${entityName} will be billed for premium request paid usage.`,
      selected: enabled === 'enable',
    },
    {
      id: 'selected',
      value: 'selected',
      title: actionMenuTitles.selected,
      description: tokenBasedBilling
        ? `Your ${entityName} will only be billed for AI credit paid usage from the selected products.`
        : `Your ${entityName} will only be billed for premium request paid usage from the selected products.`,
      selected: enabled === 'selected',
    },
    {
      id: 'disable',
      value: 'disable',
      title: actionMenuTitles.disable,
      description: tokenBasedBilling
        ? `Your ${entityName} will not be charged for AI credit overages.`
        : `Your ${entityName} will not be charged for premium request overages.`,
      selected: enabled === 'disable',
    },
  ]

  const linkToBudgets = enterprise_slug ? enterpriseBudgetsUrl(enterprise_slug) : orgBudgetsUrl(org_name)
  const isStandaloneOrg = !enterprise_name
  const isEnterpriseOwnedOrg = enterprise_name && org_name
  const slug = isStandaloneOrg ? org_name : (enterprise_slug ?? '')

  // Call the hook at the top level
  const {updateOveragePolicy, updateOveragePolicies, loading, error} = useOverageUpdate({
    slug,
    isOrg: isStandaloneOrg,
  })
  const [success, setSuccess] = useState('')
  const [dismissedError, setDismissedError] = useState('')

  const handleSelect = async (option: ActionMenuButtonOption) => {
    setEnabled(option.value as string)

    // "selected" just reveals the individual policy toggles — no API call needed
    if (option.value === 'selected') return

    const isEnabled = option.value === 'enable'
    const policies: PolicyUpdate[] = enabledAIOveragePolicies.map(type => ({
      name: type.policyName,
      type: type.type,
      enabled: isEnabled,
    }))
    setDismissedError('')
    try {
      await updateOveragePolicies(policies)
      setSuccess('Overage policies updated successfully.')
    } catch {
      setSuccess('')
    }
  }

  const handleToggle = async (aiOveragePolicy: AIOveragePolicy, toggleEnabled: boolean) => {
    setDismissedError('')
    try {
      await updateOveragePolicy(aiOveragePolicy.policyName, aiOveragePolicy.type, toggleEnabled)
      setSuccess('Overage policy updated successfully.')
    } catch {
      setSuccess('')
    }
  }

  const showError = error && error !== dismissedError

  return (
    <div style={{display: 'flex', flexWrap: 'wrap', justifyContent: 'space-between', width: '100%'}}>
      <div data-testid={`cfb-policies-overages-feature`} style={{maxWidth: 600}}>
        <PreviewFeatureHeading
          title={tokenBasedBilling ? 'AI credit paid usage' : 'Premium request paid usage'}
          beta={false}
        />
        {tokenBasedBilling
          ? `When enabled, your ${entityName} will be charged for AI credit usage that exceeds your included usage.`
          : `When enabled, your ${entityName} will be charged for premium requests that exceed your included usage.`}{' '}
        {isEnterpriseOwnedOrg && 'This setting is controlled at the enterprise level.'}
        <br />
        <Link href={linkToBudgets} inline>
          Set a budget to control your maximum spend.
        </Link>
        <br />
      </div>
      {isEnterpriseOwnedOrg ? (
        <span data-testid={`cfb-policies-overages-feature-locked`}>
          <ShieldLockIcon /> {actionMenuTitles[enabled as keyof typeof actionMenuTitles] ?? 'Policy Status Unavailable'}
        </span>
      ) : (
        <ActionMenuButton
          title={actionMenuTitles[enabled as keyof typeof actionMenuTitles]}
          options={options}
          onSelect={handleSelect}
          disabled={false}
          loading={loading}
          data-testid={`cfb-policies-overages-control`}
        />
      )}

      {showError && <BannerPortal message={error} variant="critical" onDismiss={() => setDismissedError(error)} />}
      {!showError && success && <BannerPortal message={success} variant="success" onDismiss={() => setSuccess('')} />}

      {enabled === 'selected' && (
        <>
          <ContentDivider />
          {enabledAIOveragePolicies.map((type, index, filtered) => (
            <React.Fragment key={type.id}>
              <div style={{marginLeft: 40, width: '700px'}} id={type.id} data-testid={`cfb-policies-${type.id}`}>
                <PreviewFeatureHeading title={type.title} beta={false} />
                {type.description}
              </div>

              <ToggleSwitch
                size="small"
                onChange={newValue => handleToggle(type, newValue)}
                defaultChecked={payload.overages[type.policyName]?.value === true}
                data-testid={`cfb-policies-${type.id}-switch`}
                aria-labelledby={type.id}
              />

              {index < filtered.length - 1 && (
                <div style={{marginLeft: 40, width: '100%'}}>
                  <ContentDivider />
                </div>
              )}
            </React.Fragment>
          ))}
        </>
      )}
    </div>
  )
}
